Inductive Nat : Type :=
  | Z : Nat
  | S : Nat -> Nat.

Fixpoint add (a b : Nat) : Nat :=
  match a with
  | Z => b
  | S a => S (add a b)
  end.

Lemma add_zero : forall a, add a Z = a.
Proof.
  induction a as [| a IH]; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma add_succ : forall a b, add a (S b) = S (add a b).
Proof.
  induction a as [| a IH]; intros b; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma add_comm : forall a b, add a b = add b a.
Proof.
  induction a as [| a IH]; intros b; simpl.
  - rewrite add_zero. reflexivity.
  - rewrite add_succ, IH. reflexivity.
Qed.

Inductive An0 : Type :=
  | Az0 : An0
  | As0 : An0 -> An0.

Fixpoint aadd0 (a b : An0) : An0 :=
  match a with
  | Az0 => b
  | As0 a => As0 (aadd0 a b)
  end.

Lemma aadd0_zero : forall a, aadd0 a Az0 = a.
Proof.
  induction a as [| a IH]; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma aadd0_succ : forall a b, aadd0 a (As0 b) = As0 (aadd0 a b).
Proof.
  induction a as [| a IH]; intros b; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma aadd0_comm : forall a b, aadd0 a b = aadd0 b a.
Proof.
  induction a as [| a IH]; intros b; simpl.
  - rewrite aadd0_zero. reflexivity.
  - rewrite aadd0_succ, IH. reflexivity.
Qed.

Inductive Bl1 : Type :=
  | Bn1 : Bl1
  | Bc1 : Nat -> Bl1 -> Bl1.

Fixpoint bcat1 (xs ys : Bl1) : Bl1 :=
  match xs with
  | Bn1 => ys
  | Bc1 h t => Bc1 h (bcat1 t ys)
  end.

Fixpoint blen1 (xs : Bl1) : Nat :=
  match xs with
  | Bn1 => Z
  | Bc1 h t => S (blen1 t)
  end.

Lemma bcat1_nil : forall xs, bcat1 xs Bn1 = xs.
Proof.
  induction xs as [| h t IH]; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma bcat1_assoc : forall xs ys zs, bcat1 (bcat1 xs ys) zs = bcat1 xs (bcat1 ys zs).
Proof.
  induction xs as [| h t IH]; intros ys zs; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma blen1_cat : forall xs ys, blen1 (bcat1 xs ys) = add (blen1 xs) (blen1 ys).
Proof.
  induction xs as [| h t IH]; intros ys; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Inductive Ct2 : Type :=
  | Cl2 : Nat -> Ct2
  | Cn2 : Ct2 -> Ct2 -> Ct2.

Fixpoint cmir2 (t : Ct2) : Ct2 :=
  match t with
  | Cl2 v => Cl2 v
  | Cn2 l r => Cn2 (cmir2 r) (cmir2 l)
  end.

Fixpoint csize2 (t : Ct2) : Nat :=
  match t with
  | Cl2 v => S Z
  | Cn2 l r => add (csize2 l) (csize2 r)
  end.

Lemma cmir2_mir : forall t, cmir2 (cmir2 t) = t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. reflexivity.
Qed.

Lemma csize2_mir : forall t, csize2 (cmir2 t) = csize2 t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. apply add_comm.
Qed.

