  | As753 : An753 -> An753.

Fixpoint aadd753 (a b : An753) : An753 :=
  match a with
  | Az753 => b
  | As753 a => As753 (aadd753 a b)
  end.

Lemma aadd753_zero : forall a, aadd753 a Az753 = a.
Proof.
  induction a as [| a IH]; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma aadd753_succ : forall a b, aadd753 a (As753 b) = As753 (aadd753 a b).
Proof.
  induction a as [| a IH]; intros b; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma aadd753_comm : forall a b, aadd753 a b = aadd753 b a.
Proof.
  induction a as [| a IH]; intros b; simpl.
  - rewrite aadd753_zero. reflexivity.
  - rewrite aadd753_succ, IH. reflexivity.
Qed.

Inductive Bl754 : Type :=
  | Bn754 : Bl754
  | Bc754 : Nat -> Bl754 -> Bl754.

Fixpoint bcat754 (xs ys : Bl754) : Bl754 :=
  match xs with
  | Bn754 => ys
  | Bc754 h t => Bc754 h (bcat754 t ys)
  end.

Fixpoint blen754 (xs : Bl754) : Nat :=
  match xs with
  | Bn754 => Z
  | Bc754 h t => S (blen754 t)
  end.

Lemma bcat754_nil : forall xs, bcat754 xs Bn754 = xs.
Proof.
  induction xs as [| h t IH]; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma bcat754_assoc : forall xs ys zs, bcat754 (bcat754 xs ys) zs = bcat754 xs (bcat754 ys zs).
Proof.
  induction xs as [| h t IH]; intros ys zs; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma blen754_cat : forall xs ys, blen754 (bcat754 xs ys) = add (blen754 xs) (blen754 ys).
Proof.
  induction xs as [| h t IH]; intros ys; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Inductive Ct755 : Type :=
