Fixpoint cmir755 (t : Ct755) : Ct755 :=
  match t with
  | Cl755 v => Cl755 v
  | Cn755 l r => Cn755 (cmir755 r) (cmir755 l)
  end.

Fixpoint csize755 (t : Ct755) : Nat :=
  match t with
  | Cl755 v => S Z
  | Cn755 l r => add (csize755 l) (csize755 r)
  end.

Lemma cmir755_mir : forall t, cmir755 (cmir755 t) = t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. reflexivity.
Qed.

Lemma csize755_mir : forall t, csize755 (cmir755 t) = csize755 t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. apply add_comm.
Qed.

