  | Cn1334 : Ct1334 -> Ct1334 -> Ct1334.

Fixpoint cmir1334 (t : Ct1334) : Ct1334 :=
  match t with
  | Cl1334 v => Cl1334 v
  | Cn1334 l r => Cn1334 (cmir1334 r) (cmir1334 l)
  end.

Fixpoint csize1334 (t : Ct1334) : Nat :=
  match t with
  | Cl1334 v => S Z
  | Cn1334 l r => add (csize1334 l) (csize1334 r)
  end.

Lemma cmir1334_mir : forall t, cmir1334 (cmir1334 t) = t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. reflexivity.
Qed.

Lemma csize1334_mir : forall t, csize1334 (cmir1334 t) = csize1334 t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. apply add_comm.
Qed.

Inductive An1335 : Type :=
  | Az1335 : An1335
  | As1335 : An1335 -> An1335.

Fixpoint aadd1335 (a b : An1335) : An1335 :=
  match a with
  | Az1335 => b
  | As1335 a => As1335 (aadd1335 a b)
  end.

Lemma aadd1335_zero : forall a, aadd1335 a Az1335 = a.
Proof.
  induction a as [| a IH]; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma aadd1335_succ : forall a b, aadd1335 a (As1335 b) = As1335 (aadd1335 a b).
Proof.
  induction a as [| a IH]; intros b; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma aadd1335_comm : forall a b, aadd1335 a b = aadd1335 b a.
Proof.
  induction a as [| a IH]; intros b; simpl.
  - rewrite aadd1335_zero. reflexivity.
  - rewrite aadd1335_succ, IH. reflexivity.
Qed.

