  | As1596 : An1596 -> An1596.

Fixpoint aadd1596 (a b : An1596) : An1596 :=
  match a with
  | Az1596 => b
  | As1596 a => As1596 (aadd1596 a b)
  end.

Lemma aadd1596_zero : forall a, aadd1596 a Az1596 = a.
Proof.
  induction a as [| a IH]; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma aadd1596_succ : forall a b, aadd1596 a (As1596 b) = As1596 (aadd1596 a b).
Proof.
  induction a as [| a IH]; intros b; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma aadd1596_comm : forall a b, aadd1596 a b = aadd1596 b a.
Proof.
  induction a as [| a IH]; intros b; simpl.
  - rewrite aadd1596_zero. reflexivity.
  - rewrite aadd1596_succ, IH. reflexivity.
Qed.

