  | Bc1618 : Nat -> Bl1618 -> Bl1618.

Fixpoint bcat1618 (xs ys : Bl1618) : Bl1618 :=
  match xs with
  | Bn1618 => ys
  | Bc1618 h t => Bc1618 h (bcat1618 t ys)
  end.

Fixpoint blen1618 (xs : Bl1618) : Nat :=
  match xs with
  | Bn1618 => Z
  | Bc1618 h t => S (blen1618 t)
  end.

Lemma bcat1618_nil : forall xs, bcat1618 xs Bn1618 = xs.
Proof.
  induction xs as [| h t IH]; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma bcat1618_assoc : forall xs ys zs, bcat1618 (bcat1618 xs ys) zs = bcat1618 xs (bcat1618 ys zs).
Proof.
  induction xs as [| h t IH]; intros ys zs; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma blen1618_cat : forall xs ys, blen1618 (bcat1618 xs ys) = add (blen1618 xs) (blen1618 ys).
Proof.
  induction xs as [| h t IH]; intros ys; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

