Fixpoint csize1619 (t : Ct1619) : Nat :=
  match t with
  | Cl1619 v => S Z
  | Cn1619 l r => add (csize1619 l) (csize1619 r)
  end.

Lemma cmir1619_mir : forall t, cmir1619 (cmir1619 t) = t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. reflexivity.
Qed.

Lemma csize1619_mir : forall t, csize1619 (cmir1619 t) = csize1619 t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. apply add_comm.
Qed.

