  | Cn1727 : Ct1727 -> Ct1727 -> Ct1727.

Fixpoint cmir1727 (t : Ct1727) : Ct1727 :=
  match t with
  | Cl1727 v => Cl1727 v
  | Cn1727 l r => Cn1727 (cmir1727 r) (cmir1727 l)
  end.

Fixpoint csize1727 (t : Ct1727) : Nat :=
  match t with
  | Cl1727 v => S Z
  | Cn1727 l r => add (csize1727 l) (csize1727 r)
  end.

Lemma cmir1727_mir : forall t, cmir1727 (cmir1727 t) = t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. reflexivity.
Qed.

Lemma csize1727_mir : forall t, csize1727 (cmir1727 t) = csize1727 t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
