  | Cn2411 : Ct2411 -> Ct2411 -> Ct2411.

Fixpoint cmir2411 (t : Ct2411) : Ct2411 :=
  match t with
  | Cl2411 v => Cl2411 v
  | Cn2411 l r => Cn2411 (cmir2411 r) (cmir2411 l)
  end.

Fixpoint csize2411 (t : Ct2411) : Nat :=
  match t with
  | Cl2411 v => S Z
  | Cn2411 l r => add (csize2411 l) (csize2411 r)
  end.

Lemma cmir2411_mir : forall t, cmir2411 (cmir2411 t) = t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. reflexivity.
Qed.

Lemma csize2411_mir : forall t, csize2411 (cmir2411 t) = csize2411 t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. apply add_comm.
Qed.

