Lemma bcat3196_assoc : forall xs ys zs, bcat3196 (bcat3196 xs ys) zs = bcat3196 xs (bcat3196 ys zs).
Proof.
  induction xs as [| h t IH]; intros ys zs; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma blen3196_cat : forall xs ys, blen3196 (bcat3196 xs ys) = add (blen3196 xs) (blen3196 ys).
Proof.
  induction xs as [| h t IH]; intros ys; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Inductive Ct3197 : Type :=
  | Cl3197 : Nat -> Ct3197
  | Cn3197 : Ct3197 -> Ct3197 -> Ct3197.

Fixpoint cmir3197 (t : Ct3197) : Ct3197 :=
  match t with
  | Cl3197 v => Cl3197 v
  | Cn3197 l r => Cn3197 (cmir3197 r) (cmir3197 l)
  end.

Fixpoint csize3197 (t : Ct3197) : Nat :=
  match t with
  | Cl3197 v => S Z
  | Cn3197 l r => add (csize3197 l) (csize3197 r)
  end.

Lemma cmir3197_mir : forall t, cmir3197 (cmir3197 t) = t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. reflexivity.
Qed.

Lemma csize3197_mir : forall t, csize3197 (cmir3197 t) = csize3197 t.
Proof.
  induction t as [v | l IHl r IHr]; simpl.
  - reflexivity.
  - rewrite IHl, IHr. apply add_comm.
Qed.

Inductive An3198 : Type :=
  | Az3198 : An3198
  | As3198 : An3198 -> An3198.

Fixpoint aadd3198 (a b : An3198) : An3198 :=
  match a with
  | Az3198 => b
  | As3198 a => As3198 (aadd3198 a b)
  end.

Lemma aadd3198_zero : forall a, aadd3198 a Az3198 = a.
Proof.
  induction a as [| a IH]; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma aadd3198_succ : forall a b, aadd3198 a (As3198 b) = As3198 (aadd3198 a b).
Proof.
  induction a as [| a IH]; intros b; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma aadd3198_comm : forall a b, aadd3198 a b = aadd3198 b a.
Proof.
  induction a as [| a IH]; intros b; simpl.
  - rewrite aadd3198_zero. reflexivity.
  - rewrite aadd3198_succ, IH. reflexivity.
Qed.

Inductive Bl3199 : Type :=
  | Bn3199 : Bl3199
  | Bc3199 : Nat -> Bl3199 -> Bl3199.

Fixpoint bcat3199 (xs ys : Bl3199) : Bl3199 :=
  match xs with
  | Bn3199 => ys
  | Bc3199 h t => Bc3199 h (bcat3199 t ys)
  end.

Fixpoint blen3199 (xs : Bl3199) : Nat :=
  match xs with
  | Bn3199 => Z
  | Bc3199 h t => S (blen3199 t)
  end.

Lemma bcat3199_nil : forall xs, bcat3199 xs Bn3199 = xs.
Proof.
  induction xs as [| h t IH]; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma bcat3199_assoc : forall xs ys zs, bcat3199 (bcat3199 xs ys) zs = bcat3199 xs (bcat3199 ys zs).
Proof.
  induction xs as [| h t IH]; intros ys zs; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma blen3199_cat : forall xs ys, blen3199 (bcat3199 xs ys) = add (blen3199 xs) (blen3199 ys).
Proof.
  induction xs as [| h t IH]; intros ys; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

